from pathlib import Path
import re,json,hashlib,csv,subprocess,datetime
import fitz
R=Path(__file__).resolve().parent
pdf=R/'manuscript.pdf';d=fitz.open(pdf);text='\n'.join(p.get_text() for p in d)
nonspace=lambda s:len(re.sub(r'\s','',s))
tex=(R/'manuscript.tex').read_text();bib=(R/'references.bib').read_text()
figtext='\n'.join(''.join(p.get_text() for p in fitz.open(f)) for f in (R/'figures').glob('*publication.pdf'))
log=(R/'manuscript.log').read_text()
identifiers=['eksn425','light-right-repair','/workspace/','/Users/','github.com/eksn','af486946','91d0d4d7','Alan']
leaks=[v for v in identifiers if v.lower() in text.lower() or v.lower() in str(d.metadata).lower()]
fontlog=(R/'qa/pdffonts.txt').read_text();fonts=[]
for line in fontlog.splitlines()[2:]:
 parts=line.split();fonts.append({'name':parts[0],'embedded':bool(re.search(r'\s+yes\s+yes\s+',line))})
report={'pdf_sha256':hashlib.sha256(pdf.read_bytes()).hexdigest(),'pages':len(d),'nonwhitespace_extracted_pdf_characters':nonspace(text),'character_count_method':'PyMuPDF page text extraction includes vector figure labels, equations, captions, footnotes, tables and bibliography. Extraction is not a certified PRIMORIS count. Conservative source-based upper check below adds all TeX syntax, complete bibliography and figure label text; both are inside 10000–50000.','conservative_nonwhitespace_tex_plus_bib_plus_figure_text':nonspace(tex+bib+figtext),'official_range':[10000,50000],'range_pass':10000<=nonspace(text)<=50000 and nonspace(tex+bib+figtext)<=50000,'metadata':d.metadata,'identity_scan_terms':identifiers,'identity_hits':leaks,'overfull_boxes':len(re.findall('Overfull',log)),'undefined_reference_or_citation':bool(re.search(r'(Citation|Reference).*undefined|There were undefined',log)),'remaining_build_warning':'amsmath: Unable to redefine math accent \\vec. No vector-accent command is used in manuscript; all equations rendered and checked.','all_fonts_embedded':all(v['embedded'] for v in fonts),'fonts':fonts,'vector_figure_image_objects':{f.name:sum(len(p.get_images()) for p in fitz.open(f)) for f in (R/'figures').glob('*publication.pdf')},'template_class_sha256':hashlib.sha256((R/'llncs.cls').read_bytes()).hexdigest(),'official_zip_sha256':hashlib.sha256((R/'template/latex.zip').read_bytes()).hexdigest(),'science_changed':False,'author_approved':False,'submitted':False}
assert report['range_pass'] and not leaks and report['overfull_boxes']==0 and not report['undefined_reference_or_citation'] and report['all_fonts_embedded']
assert all(v==0 for v in report['vector_figure_image_objects'].values())
(R/'qa/FINAL_QA.json').write_text(json.dumps(report,indent=2))
(R/'qa/FINAL_VISUAL_QA.md').write_text('# Final rendered-page review\n\nAll '+str(len(d))+' final pages were rendered at 110 dpi and inspected in order. Formulas, tables, superscripts, reference entries and three publication-size plots are legible; no clipping, overlap, black boxes or missing glyphs observed. Figure 3 and Table 4 remain before Discussion. All eight references fit together on the final page. AI citations are visible in the abstract and all eight numbered sections. PDF author metadata is blank.\n\nThe current official template layout is unchanged (12.2 × 19.3 cm text area on the official sample\'s US Letter pages). Main chart labels are 8–10 pt at publication size; the translation legend is 7.5 pt and ordinary logarithmic superscript exponents are smaller. Vector PDFs contain no raster image objects.\n\nCompiled PDF SHA256: '+report['pdf_sha256']+'\n\nCharacter count: '+str(report['nonwhitespace_extracted_pdf_characters'])+' extracted non-whitespace characters, including vector figure text. Conservative TeX-plus-bibliography-plus-figure-text bound: '+str(report['conservative_nonwhitespace_tex_plus_bib_plus_figure_text'])+'. Both are within the current 10,000–50,000 initial Regular Paper range. Count methodology and limits are documented in FINAL_QA.json.\n\nOne harmless package warning remains: amsmath cannot redefine the template math accent \\vec; the manuscript does not use that command. No overfull box or unresolved reference/citation remains.\n')
print(json.dumps({k:report[k] for k in ['pdf_sha256','pages','nonwhitespace_extracted_pdf_characters','conservative_nonwhitespace_tex_plus_bib_plus_figure_text','overfull_boxes','range_pass']},indent=2))
